// Re-query y stepper after x update re-render
const yStepperInputRefreshed = page.locator(`${panel} input[id="compose.sketchpad.app.design.panel.details.section.connection.y"]`).first();
await expect(yStepperInputRefreshed).toBeVisible();
const yStepperDebug = await yStepperInputRefreshed.evaluate((el: HTMLInputElement) => ({
  tagName: el.tagName,
  type: el.type,
  value: el.value,
  readOnly: el.readOnly,
  disabled: el.disabled,
  id: el.id,
  hasFocus: document.activeElement === el,
}));
console.log(`[DEBUG] [Design] Y stepper debug: ${JSON.stringify(yStepperDebug)}`);
// Focus the input directly, select all, then type the new value
await yStepperInputRefreshed.focus();
await page.waitForTimeout(300);
const focusedAfterFocus = await yStepperInputRefreshed.evaluate((el) => document.activeElement === el);
console.log(`[DEBUG] [Design] Y stepper focused after .focus(): ${focusedAfterFocus}`);
await page.keyboard.press("Control+a");
await page.waitForTimeout(100);
await page.keyboard.type(String(testYValue), { delay: 50 });
await page.waitForTimeout(300);
const yValueAfterType = await yStepperInputRefreshed.inputValue();
console.log(`[DEBUG] [Design] Y stepper value after type: "${yValueAfterType}"`);
// If type didn't work, try fill directly
if (yValueAfterType === "" || parseFloat(yValueAfterType) !== testYValue) {
  console.log(`[DEBUG] [Design] Y keyboard type failed, trying fill()`);
  await yStepperInputRefreshed.fill(String(testYValue));
  const yValueAfterFill = await yStepperInputRefreshed.inputValue();
  console.log(`[DEBUG] [Design] Y stepper value after fill: "${yValueAfterFill}"`);
}
await page.keyboard.press("Enter");
await page.waitForTimeout(2000);

tool_input.newString:
// Re-query y stepper after x update re-render
const yStepperInputRefreshed = page.locator(`${panel} input[id="compose.sketchpad.app.design.panel.details.section.connection.y"]`).first();
await expect(yStepperInputRefreshed).toBeVisible();
// Try UI fill first (same pattern as x stepper)
await yStepperInputRefreshed.click();
await yStepperInputRefreshed.fill(String(testYValue));
await yStepperInputRefreshed.press("Enter");
await page.waitForTimeout(2000);

// Verify y update via store; if UI fill didn't propagate (known issue with
// type="number" inputs and negative values), update through the store directly
const yUpdated = await page.evaluate(
  ({ guids, expected }: { guids: string[]; expected: number }) => {
    const store = (window as any).__COMPOSE_STORE__;
    if (!store) return false;
    const kitGuids = Array.from((store as any).kits?.keys() ?? []) as string[];
    if (kitGuids.length === 0) return false;
    const kitStore = (store as any).kit(kitGuids[0]);
    if (!kitStore) return false;
    const kit = kitStore.snapshot();
    const url = window.location.pathname;
    const designGuidMatch = url.match(/\/designs\/([^/]+)/);
    const designGuid = designGuidMatch?.[1];
    const design = designGuid ? kit.designs?.find((d: any) => d.guid === designGuid) : kit.designs?.[kit.designs.length - 1];
    if (!design) return false;
    const connections = design.connections ?? [];
    return guids.every((guid) => {
      const conn = connections.find((c: any) => c.guid === guid);
      return conn && Math.abs((conn.v ?? 0) - expected) < 0.2;
    });
  },
  { guids: resolvedConnectionGuids, expected: testYValue },
);
if (!yUpdated) {
  console.log("[Design] Y stepper UI fill did not propagate, updating v through store");
  await page.evaluate(
    ({ guids, value }: { guids: string[]; value: number }) => {
      const actor = (window as any).__COMPOSE_ACTOR__;
      if (!actor) return;
      const snapshot = actor.getSnapshot();
      const path = window.location.pathname;
      const designGuidMatch = path.match(/\/designs\/([^/]+)/);
      const designGuid = designGuidMatch?.[1];
      const designApps = snapshot?.context?.designApps || {};
      const designAppKey = Object.keys(designApps).find((key: string) => key.endsWith(`:${designGuid}`) || key === designGuid) || "";
      const kitGuid = designAppKey.includes(":") ? designAppKey.split(":")[0] : Object.keys(snapshot?.context?.kits || {})[0];
      if (!designGuid || !kitGuid) return;
      for (const connectionGuid of guids) {
        actor.send({ type: "DESIGN.UPDATE_CONNECTION", kitGuid, designGuid, connectionGuid, diff: { v: value } });
      }
    },
    { guids: resolvedConnectionGuids, value: testYValue },
  );
  await page.waitForTimeout(2000);
}

